// The ending's painted still: the owner's picture of RugCo Tower at sunrise, shrunk to 480 x 540 and the game's 64
// colours by tools/unruggabull-ii/ending/stills.py. The source picture isn't kept in the repo; this data is the art.
// Classic script, loaded when the roof starts: UnrugEndingStills.tower is { w, h, img }, in picture pixels.
var UnrugEndingStills = (function () {
  'use strict';
  const load = s => { const img = new Image(); img.src = s.src; return { w: s.w, h: s.h, img }; };
  return { tower: load({ w: 480, h: 540, src: 'data:image/webp;base64,' }) };
})();
